def validate(source,source_sha,output,go="go"):
    receipt=BASE.validate(source,source_sha,output,go)
    # The original validator has already joined every process and rechecked
    # both generated trees, all images and the complete selected source.
    receipt.update(scope="original-encrypted-owner-and-typed-native-MTU-component-composition",
        preserved_typed_cases=list(ORIGINAL_TYPED),preserved_box_cases=list(ORIGINAL_BOX),
        native_mtu_cases=list(NATIVE_CASES),libbox_mtu_cases=list(WRAPPER_CASES),
        native_mtu_component_accepted=True,public_mtu_constructor_accepted=False,
        generated_sdk_accepted=False,physical_mtu_accepted=False,
        mtu_component_boundaries=["OS TUN reader and interface observation","existing packet/proof component boundary"],
        trusted_extended_validator_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest())
    for name in ("receipt.json","progress.json"):
        path=Path(output)/name;temporary=path.with_suffix(".tmp")
        temporary.write_text(json.dumps(receipt,indent=2)+"\n");temporary.replace(path)
    return receipt

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--suite",required=True,choices=(SUITE,))
    parser.add_argument("--source",required=True,type=Path)
    parser.add_argument("--source-sha",required=True)
    parser.add_argument("--output",required=True,type=Path)
    parser.add_argument("--go",default="go")
    args=parser.parse_args();validate(args.source,args.source_sha,args.output,args.go)
if __name__=="__main__":main()
